package com.amilingo.platform.module.patent.service;
import com.amilingo.platform.module.patent.dto.PatentOperationsDTO.*;import com.amilingo.platform.module.patent.entity.*;import com.amilingo.platform.module.patent.repository.*;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.stream.Collectors;

@Service @RequiredArgsConstructor
public class PatentOperationsService{
 private final PatentRepository patentRepo;private final PatentDocumentRepository documentRepo;private final PatentClaimRepository claimRepo;
 private final PatentOfficeActionRepository actionRepo;private final PatentDeadlineRepository deadlineRepo;private final PatentFeeRepository feeRepo;

 @Transactional public PatentDocument addDocument(Long patentId,DocumentRequest r){owned(patentId,r.actorUserId());return documentRepo.save(PatentDocument.builder().patentId(patentId).relatedRecordId(r.relatedRecordId()).category(r.category()).fileName(r.fileName()).contentType(r.contentType()).fileSize(r.fileSize()).storageKey(r.storageKey()).fileUrl(r.fileUrl()).fileHash(r.fileHash()).versionNo(r.versionNo()).uploadedBy(r.actorUserId()).status("ACTIVE").build());}
 @Transactional public void deleteDocument(Long id,Long actor){PatentDocument d=documentRepo.findById(id).orElseThrow(()->new IllegalArgumentException("申请材料不存在"));owned(d.getPatentId(),actor);d.setStatus("DELETED");documentRepo.save(d);}
 public List<PatentDocument> documents(Long patentId,Long actor,String category){owned(patentId,actor);return category==null||category.isBlank()?documentRepo.findByPatentIdAndStatusOrderByCreatedAtDesc(patentId,"ACTIVE"):documentRepo.findByPatentIdAndCategoryAndStatusOrderByCreatedAtDesc(patentId,category,"ACTIVE");}

 @Transactional public PatentClaim createClaim(Long patentId,ClaimRequest r){owned(patentId,r.actorUserId());if(claimRepo.existsByPatentIdAndClaimNoAndCurrentVersionTrue(patentId,r.claimNo()))throw new IllegalArgumentException("权利要求编号已存在");validateClaimParent(patentId,r);return claimRepo.save(toClaim(patentId,1,r));}
 @Transactional public PatentClaim reviseClaim(Long id,ClaimRequest r){PatentClaim source=claimRepo.findById(id).orElseThrow(()->new IllegalArgumentException("权利要求不存在"));owned(source.getPatentId(),r.actorUserId());if(!source.getClaimNo().equals(r.claimNo()))throw new IllegalArgumentException("修订时不能改变权利要求编号");validateClaimParent(source.getPatentId(),r);List<PatentClaim> versions=claimRepo.findByPatentIdAndClaimNoOrderByVersionNoDesc(source.getPatentId(),source.getClaimNo());versions.stream().filter(PatentClaim::getCurrentVersion).forEach(x->{x.setCurrentVersion(false);claimRepo.save(x);});int next=versions.stream().mapToInt(PatentClaim::getVersionNo).max().orElse(0)+1;return claimRepo.save(toClaim(source.getPatentId(),next,r));}
 public List<PatentClaim> claims(Long patentId,Long actor){owned(patentId,actor);return claimRepo.findByPatentIdAndCurrentVersionTrueOrderByClaimNoAsc(patentId);}
 public List<PatentClaim> claimVersions(Long patentId,Integer no,Long actor){owned(patentId,actor);return claimRepo.findByPatentIdAndClaimNoOrderByVersionNoDesc(patentId,no);}

 @Transactional public PatentOfficeAction createOfficeAction(Long patentId,OfficeActionRequest r){owned(patentId,r.actorUserId());if(r.responseDeadline().isBefore(r.noticeDate()))throw new IllegalArgumentException("答复截止日期不能早于通知日期");int round=actionRepo.findFirstByPatentIdOrderByRoundNoDesc(patentId).map(x->x.getRoundNo()+1).orElse(1);PatentOfficeAction a=actionRepo.save(PatentOfficeAction.builder().patentId(patentId).roundNo(round).actionType(r.actionType()).noticeDate(r.noticeDate()).responseDeadline(r.responseDeadline()).opinionContent(r.opinionContent()).assigneeUserId(r.assigneeUserId()).status("PENDING").attachments(join(r.attachments())).build());deadlineRepo.save(PatentDeadline.builder().patentId(patentId).relatedRecordId(a.getId()).type("OFFICE_ACTION_RESPONSE").title("第 "+round+" 轮审查意见答复").dueDate(r.responseDeadline()).remindDaysBefore(7).priority("HIGH").status("PENDING").build());return a;}
 @Transactional public PatentOfficeAction respondOfficeAction(Long id,OfficeActionResponseRequest r){PatentOfficeAction a=actionRepo.findById(id).orElseThrow(()->new IllegalArgumentException("审查意见不存在"));owned(a.getPatentId(),r.actorUserId());if("RESPONDED".equals(a.getStatus()))throw new IllegalStateException("该审查意见已经答复");if(r.responseClaimVersionId()!=null){PatentClaim c=claimRepo.findById(r.responseClaimVersionId()).orElseThrow(()->new IllegalArgumentException("权利要求版本不存在"));if(!a.getPatentId().equals(c.getPatentId()))throw new IllegalArgumentException("权利要求版本不属于当前专利");}a.setResponseContent(r.responseContent());a.setResponseClaimVersionId(r.responseClaimVersionId());a.setAttachments(join(r.attachments()));a.setStatus("RESPONDED");a.setRespondedAt(LocalDateTime.now());deadlineRepo.findByPatentIdOrderByDueDateAsc(a.getPatentId()).stream().filter(d->a.getId().equals(d.getRelatedRecordId())&&"OFFICE_ACTION_RESPONSE".equals(d.getType())&&"PENDING".equals(d.getStatus())).forEach(d->{d.setStatus("COMPLETED");d.setCompletedAt(LocalDateTime.now());deadlineRepo.save(d);});return actionRepo.save(a);}
 public List<PatentOfficeAction> officeActions(Long patentId,Long actor){owned(patentId,actor);return actionRepo.findByPatentIdOrderByRoundNoDesc(patentId);}

 @Transactional public PatentDeadline createDeadline(Long patentId,DeadlineRequest r){owned(patentId,r.actorUserId());return deadlineRepo.save(PatentDeadline.builder().patentId(patentId).relatedRecordId(r.relatedRecordId()).type(r.type()).title(r.title()).dueDate(r.dueDate()).remindDaysBefore(r.remindDaysBefore()).priority(r.priority()).status("PENDING").notes(r.notes()).build());}
 @Transactional public PatentDeadline updateDeadlineStatus(Long id,DeadlineStatusRequest r){PatentDeadline d=deadlineRepo.findById(id).orElseThrow(()->new IllegalArgumentException("期限不存在"));owned(d.getPatentId(),r.actorUserId());d.setStatus(r.status());d.setCompletedAt("COMPLETED".equals(r.status())?LocalDateTime.now():null);return deadlineRepo.save(d);}
 public List<DeadlineView> deadlines(Long patentId,Long actor){owned(patentId,actor);return deadlineRepo.findByPatentIdOrderByDueDateAsc(patentId).stream().map(this::view).toList();}
 public List<DeadlineView> dueReminders(Long actor,int days){LocalDate limit=LocalDate.now().plusDays(Math.max(0,days));return deadlineRepo.findByStatusAndDueDateLessThanEqualOrderByDueDateAsc("PENDING",limit).stream().filter(d->patentRepo.findById(d.getPatentId()).map(p->p.getUserId().equals(actor)).orElse(false)).map(this::view).toList();}

 @Transactional public PatentFee createFee(Long patentId,FeeRequest r){owned(patentId,r.actorUserId());if(r.reductionAmount()!=null&&r.reductionAmount().compareTo(r.amount())>0)throw new IllegalArgumentException("减缴金额不能大于应缴金额");return feeRepo.save(PatentFee.builder().patentId(patentId).type(r.type()).amount(r.amount()).currency(r.currency()).reductionAmount(r.reductionAmount()).dueDate(r.dueDate()).status("UNPAID").notes(r.notes()).build());}
 @Transactional public PatentFee payFee(Long id,FeePaymentRequest r){PatentFee f=feeRepo.findById(id).orElseThrow(()->new IllegalArgumentException("费用记录不存在"));owned(f.getPatentId(),r.actorUserId());if("PAID".equals(f.getStatus()))throw new IllegalStateException("该费用已经支付");f.setPaidDate(r.paidDate());f.setReceiptDocumentKey(r.receiptDocumentKey());f.setStatus("PAID");return feeRepo.save(f);}
 @Transactional public void deleteFee(Long id,Long actor){PatentFee f=feeRepo.findById(id).orElseThrow(()->new IllegalArgumentException("费用记录不存在"));owned(f.getPatentId(),actor);if("PAID".equals(f.getStatus()))throw new IllegalArgumentException("已支付费用不能删除");feeRepo.delete(f);}
 public List<PatentFee> fees(Long patentId,Long actor){owned(patentId,actor);return feeRepo.findByPatentIdOrderByDueDateAscIdAsc(patentId);}
 public FeeSummary feeSummary(Long patentId,Long actor){List<PatentFee> fees=fees(patentId,actor);Set<String> currencies=fees.stream().map(PatentFee::getCurrency).collect(Collectors.toSet());String currency=currencies.size()<=1?currencies.stream().findFirst().orElse("CNY"):"MIXED";BigDecimal payable=fees.stream().map(this::net).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal paid=fees.stream().filter(x->"PAID".equals(x.getStatus())).map(this::net).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,BigDecimal> byType=fees.stream().collect(Collectors.groupingBy(PatentFee::getType,Collectors.reducing(BigDecimal.ZERO,this::net,BigDecimal::add)));return new FeeSummary(payable,paid,payable.subtract(paid),byType,currency);}

 private Patent owned(Long id,Long actor){Patent p=patentRepo.findById(id).orElseThrow(()->new IllegalArgumentException("专利不存在"));if(!p.getUserId().equals(actor))throw new SecurityException("无权操作该专利");return p;}
 private PatentClaim toClaim(Long p,int version,ClaimRequest r){return PatentClaim.builder().patentId(p).claimNo(r.claimNo()).versionNo(version).type(r.type()).parentClaimNo(r.parentClaimNo()).content(r.content()).technicalFeatures(r.technicalFeatures()).supportReference(r.supportReference()).currentVersion(true).createdBy(r.actorUserId()).build();}
 private void validateClaimParent(Long patentId,ClaimRequest r){if("INDEPENDENT".equals(r.type())&&r.parentClaimNo()!=null)throw new IllegalArgumentException("独立权利要求不能引用父权利要求");if("DEPENDENT".equals(r.type())){if(r.parentClaimNo()==null)throw new IllegalArgumentException("从属权利要求必须引用父权利要求");if(r.claimNo().equals(r.parentClaimNo()))throw new IllegalArgumentException("权利要求不能引用自身");if(!claimRepo.existsByPatentIdAndClaimNoAndCurrentVersionTrue(patentId,r.parentClaimNo()))throw new IllegalArgumentException("引用的父权利要求不存在");}}
 private DeadlineView view(PatentDeadline d){long days=ChronoUnit.DAYS.between(LocalDate.now(),d.getDueDate());String urgency=days<0?"OVERDUE":days==0?"TODAY":days<=3?"URGENT":days<=d.getRemindDaysBefore()?"UPCOMING":"NORMAL";return new DeadlineView(d.getId(),d.getPatentId(),d.getType(),d.getTitle(),d.getDueDate(),days,urgency,d.getStatus());}
 private BigDecimal net(PatentFee f){return f.getAmount().subtract(f.getReductionAmount()==null?BigDecimal.ZERO:f.getReductionAmount());}private String join(List<String>x){return x==null||x.isEmpty()?null:String.join(",",x);}
}
